// 实际活跃策略与原本人必须双重匹配；此短栈回调不会持有临时World或越过原任务优先级。
#include "political_office_resignation_response_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Outcome<StableId> policy_id(const WorldBundle& w,const StableId& actor){if(!w.catalog->director||!w.catalog->director->office_resignation_responses||!w.catalog->political_office_resignations||w.catalog->political_office_resignations->version!=2||actor==w.common.state().metadata.player_actor_id)return {false,{},common_failure("OfficeResignationResponseProfileRequired",actor).error};const auto* policy=director_policy(w.director,*w.catalog->director,actor);if(!policy||!director_subject_active(w.director,actor)||!policy->office_resignation_response_intent_id||std::find(policy->templates.begin(),policy->templates.end(),DirectorTemplate::office_resignation_response)==policy->templates.end())return {false,{},common_failure("OfficeResignationResponseDirectorPolicyMismatch",actor).error};if(w.catalog->director->dynamic_subjects){const auto* r=w.director.registrations.find(actor);if(!r||r->obligations_only)return {false,{},common_failure("OfficeResignationResponseDirectorPolicyMismatch",actor).error};return {true,r->policy_id,{}};}return {true,actor,{}};}
Status guard(const WorldBundle& w,const StableId& actor,const AuthoredOfficeResignationCommand& command){auto valid=command_common_guard(w,actor,political_office_resignation_answer_command);if(!valid.ok)return valid;auto id=policy_id(w,actor);if(!id.ok)return {false,{},id.error};const auto* p=director_policy(w.director,*w.catalog->director,actor);return command.origin.actor_id==actor&&command.origin.director_policy_id==id.value&&p&&p->office_resignation_response_intent_id==std::optional<StableId>{command.origin.intent_id}?common_success():common_failure("OfficeResignationResponseOriginMismatch",actor);}
class Read final:public PoliticalOfficeResignationResponseRead {
 const PoliticalOfficeResignationContext& x_;
public:
 explicit Read(const PoliticalOfficeResignationContext& x):x_(x){}
 Outcome<PoliticalOfficeResignationResponseKnown> known_response(const StableId& actor,const PoliticalOfficeResignationResponseIntent& intent)const override{return read_political_office_resignation_response_known(x_,actor,intent);}
 Outcome<std::shared_ptr<const CommandPayload>> preview_response_local(const StableId& actor,const PoliticalOfficeResignationResponseIntent& intent,const PoliticalOfficeResignationResponseKnown& known)const override{auto command=preview_political_office_resignation_response_local(x_,actor,intent,known);return command.ok?Outcome<std::shared_ptr<const CommandPayload>>{true,std::make_shared<const CommandPayload>(CommandPayload{political_office_resignation_answer_command,std::move(command.value)}),{}}:Outcome<std::shared_ptr<const CommandPayload>>{false,{},command.error};}
};
}
Outcome<std::optional<DecisionProposal>> propose_political_office_resignation_response_world(const WorldBundle& w,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){auto id=policy_id(w,known.actor_id);if(!id.ok)return id.error.kind==ErrorKind::rule?Outcome<std::optional<DecisionProposal>>{true,std::nullopt,{}}:Outcome<std::optional<DecisionProposal>>{false,{},id.error};if(!w.catalog->travel||!policy.office_resignation_response_intent_id)return {false,{},common_failure("OfficeResignationResponseWorldProfileRequired").error};const auto* intent=w.catalog->director->office_resignation_responses->intents.find(*policy.office_resignation_response_intent_id);if(!intent)return {false,{},common_failure("OfficeResignationResponseIntentMismatch").error};auto holder=PoliticalOfficeResignationWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};Read read(holder.value->context());PoliticalOfficeResignationResponseDirectorContext context{w.common,*w.catalog->travel,*w.catalog->political_successions,*w.catalog->political_office_resignations,read,id.value};return propose_director_office_resignation_response(context,known,policy,*intent,base,w.catalog->director->candidates_per_subject);}
Outcome<PoliticalOfficeResignationQuote> prepare_authored_office_resignation_world(const WorldBundle& w,const StableId& actor,const AuthoredOfficeResignationCommand& command){auto valid=guard(w,actor,command);if(!valid.ok)return {false,{},valid.error};auto holder=PoliticalOfficeResignationWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};auto rules=holder.value->context();rules.authored_command=&command.origin;return preview_political_office_resignation(rules,actor,command.command);}
Outcome<PoliticsEffects> commit_authored_office_resignation_world(WorldBundle& w,const StableId& actor,const AuthoredOfficeResignationCommand& command,const PoliticalOfficeResignationQuote& quote){auto valid=guard(w,actor,command);if(!valid.ok)return {false,{},valid.error};auto holder=PoliticalOfficeResignationWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};auto rules=holder.value->context();rules.authored_command=&command.origin;return apply_political_office_resignation_business_in_candidate(w.common,w.organization,*w.political_office_resignations,rules,actor,command.command,quote);}
// 原本域来源和完整Family/Office后必调；无模块时拒漂浮18计划，不加旧段空尾。
Status validate_political_office_resignation_response_world(const WorldBundle& w){if(!w.catalog->director)return w.catalog->political_office_resignations&&w.catalog->political_office_resignations->version==2?common_failure("OfficeResignationResponseVersionPairRequired"):common_success();const bool enabled=bool(w.catalog->director->office_resignation_responses);if(enabled!=bool(w.catalog->political_office_resignations&&w.catalog->political_office_resignations->version==2))return common_failure("OfficeResignationResponseVersionPairRequired");if(!enabled)return validate_political_office_resignation_response_director(*w.catalog->director,w.director,nullptr);auto holder=PoliticalOfficeResignationWorldAccess::create(w);return holder.ok?validate_political_office_resignation_response_director(*w.catalog->director,w.director,&holder.value->context()):Status{false,{},holder.error};}
}
